<?php
session_start();
require_once __DIR__ . '/conexion.php';
if (!isset($_SESSION['id_usuario']) || ($_SESSION['rol'] ?? '') !== 'administrador') { http_response_code(403); exit('Acceso no autorizado'); }
function h($v) { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
if (empty($_SESSION['csrf'])) $_SESSION['csrf'] = bin2hex(random_bytes(32));
$error = '';
$success = isset($_GET['ok']);
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
 if (!hash_equals($_SESSION['csrf'], (string)($_POST['csrf'] ?? ''))) { http_response_code(403); exit('Solicitud inválida'); }
 try {
  $nombre=trim((string)($_POST['nombre']??''));
  $identificacion=trim((string)($_POST['identificacion']??''));
  $telefono=trim((string)($_POST['telefono']??''));
  $correo=trim((string)($_POST['correo']??''));
  $direccion=trim((string)($_POST['direccion_residencia']??''));
  $municipio=trim((string)($_POST['municipio_residencia']??''));
  $contacto=trim((string)($_POST['contacto_emergencia']??''));
  $telefono_em=trim((string)($_POST['telefono_emergencia']??''));
  if ($nombre==='' || mb_strlen($nombre)>160 || mb_strlen($identificacion)>60 || mb_strlen($telefono)>35 || mb_strlen($correo)>190 || ($correo!=='' && !filter_var($correo,FILTER_VALIDATE_EMAIL)) || mb_strlen($direccion)>255 || mb_strlen($municipio)>120 || mb_strlen($contacto)>160 || mb_strlen($telefono_em)>35) { $error='Revisa el nombre, correo y longitudes de los campos.'; }
  else { $s=$conexion->prepare('INSERT INTO pilotos (nombre,identificacion,telefono,correo,direccion_residencia,municipio_residencia,contacto_emergencia,telefono_emergencia,activo) VALUES (?,?,?,?,?,?,?,?,1)'); $s->execute([$nombre,$identificacion?:null,$telefono?:null,$correo?:null,$direccion?:null,$municipio?:null,$contacto?:null,$telefono_em?:null]); header('Location: pilotos.php?ok=1'); exit; }
 } catch (PDOException $e) { error_log($e->getMessage()); $error = 'No se pudo guardar. Revisa los datos o si el registro ya existe.'; }
}
$rows=$conexion->query('SELECT id_piloto,nombre,identificacion,telefono,correo,municipio_residencia,activo FROM pilotos ORDER BY id_piloto DESC')->fetchAll();
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Registro de pilotos | Transmetro</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f5f7fb;color:#243044}.navbar{background:#14253e}.card{border:0;border-radius:16px;box-shadow:0 6px 22px #14253e13}.btn-brand{background:#f0a72e;color:#14253e;font-weight:700}.btn-brand:hover{background:#e9a01d}</style></head><body><nav class="navbar navbar-dark"><div class="container"><a class="navbar-brand fw-bold" href="panel.php">Transmetro Info</a><a class="btn btn-outline-light btn-sm" href="panel.php">Volver al panel</a></div></nav><main class="container py-5"><h1 class="h3 fw-bold">Registro de pilotos</h1><p class="text-secondary">Módulo administrativo · Proyecto académico</p><?php if ($success): ?><div class="alert alert-success">Registro guardado correctamente.</div><?php endif; ?><?php if ($error): ?><div class="alert alert-danger"><?= h($error) ?></div><?php endif; ?><div class="card mb-4"><div class="card-body p-4"><h2 class="h5">Nuevo piloto</h2><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><div class="col-md-6"><label class="form-label">Nombre completo *</label><input name="nombre" maxlength="160" required class="form-control"></div><div class="col-md-6"><label class="form-label">Identificación</label><input name="identificacion" maxlength="60" class="form-control"></div><div class="col-md-6"><label class="form-label">Teléfono</label><input name="telefono" maxlength="35" class="form-control"></div><div class="col-md-6"><label class="form-label">Correo</label><input name="correo" type="email" maxlength="190" class="form-control"></div><div class="col-md-6"><label class="form-label">Dirección de residencia</label><input name="direccion_residencia" maxlength="255" class="form-control"></div><div class="col-md-6"><label class="form-label">Municipio de residencia</label><input name="municipio_residencia" maxlength="120" class="form-control"></div><div class="col-md-6"><label class="form-label">Contacto de emergencia</label><input name="contacto_emergencia" maxlength="160" class="form-control"></div><div class="col-md-6"><label class="form-label">Teléfono de emergencia</label><input name="telefono_emergencia" maxlength="35" class="form-control"></div><div class="col-12"><button class="btn btn-brand">Guardar piloto</button></div></form></div></div><div class="card"><div class="card-body p-4"><h2 class="h5">Pilotos registrados</h2><div class="table-responsive"><table class="table table-hover"><thead><tr><th>ID</th><th>Nombre</th><th>Identificación</th><th>Teléfono</th><th>Correo</th><th>Municipio</th><th>Estado</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= (int)$r['id_piloto']?></td><td><?=h($r['nombre'])?></td><td><?=h($r['identificacion'])?></td><td><?=h($r['telefono'])?></td><td><?=h($r['correo'])?></td><td><?=h($r['municipio_residencia'])?></td><td><?= (int)$r['activo']===1?'Activo':'Inactivo'?></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="7">Sin pilotos registrados.</td></tr><?php endif; ?></tbody></table></div><p class="text-secondary small mb-0">Utiliza datos ficticios para la demostración. El historial educativo se añadirá en otro módulo.</p></div></div></main></body></html>